def user_language(db_path, user_id, telegram_language=None):
    ensure_user_settings_schema(db_path)
    with closing(sqlite3.connect(db_path)) as conn:
        row = conn.execute(
            "SELECT ui_language_override, detected_ui_language FROM user_settings WHERE user_id=?",
            (str(user_id),),
        ).fetchone()
    return normalize_telegram_language(
        (row[0] if row else None) or telegram_language or (row[1] if row else None)
    )


