TEXTS = {language: dict(zip(KEYS, values.split("|"), strict=True)) for language, values in COPY.items()}


def text(language, key, **values):
    return TEXTS[normalize_telegram_language(language)][key].format(**values)


def values(key):
    return tuple(dict.fromkeys(copy[key] for copy in TEXTS.values()))
